+NS_IMETHODIMP nsMsgHdr::GetIsLive(bool* isLive) {
+  // If it's attached to the messages table, it's live.
+  bool found = false;
+  nsresult rv = m_mdb->ContainsKey(m_messageKey, &found);
+  NS_ENSURE_SUCCESS(rv, rv);
+  *isLive = found;
+  return NS_OK;
+}
